"use client";

import { InlineLoading, InlineNotification } from "@carbon/react";
import { useRouter } from "next/navigation";
import { useEffect } from "react";
import { application } from "@/application";
import { homeOf } from "./access";
import { useSession } from "./session";
import { say, type Texts } from "./texts";

export interface HomeProps {
  readonly texts: Texts;
}

/**
 * The application's start: once the session is read, it opens the home of
 * the first of the person's roles that has one, sends someone signed out to
 * sign in, and leaves anyone else at the menu.
 */
export function Home({ texts }: HomeProps) {
  const router = useRouter();
  const session = useSession();
  const home = session ? homeOf(application.homes ?? {}, session) : undefined;
  const signIn = session !== undefined && session !== null && !session.signedIn && application.signIn !== null;
  useEffect(() => {
    if (home !== undefined) {
      router.replace(home);
    } else if (signIn && application.signIn !== null) {
      router.replace(application.signIn + "?returnTo=" + encodeURIComponent("/"));
    }
  }, [home, signIn, router]);
  if (session === null) {
    return <InlineNotification kind="error" role="alert" lowContrast hideCloseButton title={say(texts, "screens.failed")} />;
  }
  if (session === undefined || home !== undefined || signIn) {
    return <InlineLoading description={say(texts, "screens.loading")} />;
  }
  return null;
}
